/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var dlanhs = require( './../lib/dlanhs.js' );


// FIXTURES //

var ROW_MAJOR_DATA = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_DATA = require( './fixtures/column_major.json' );


// FUNCTIONS //

/**
* Asserts that the function computes the expected value for each supported norm.
*
* @private
* @param {Object} t - test object
* @param {Object} data - fixture data
*/
function isExpected( t, data ) {
	var work = new Float64Array( data.N );
	t.strictEqual( dlanhs( data.order, 'max', data.N, new Float64Array( data.A ), data.LDA, work ), data.expectedMax, 'returns expected value' );
	t.strictEqual( dlanhs( data.order, 'one', data.N, new Float64Array( data.A ), data.LDA, work ), data.expectedOne, 'returns expected value' );
	t.strictEqual( dlanhs( data.order, 'inf', data.N, new Float64Array( data.A ), data.LDA, work ), data.expectedInf, 'returns expected value' );
	t.strictEqual( dlanhs( data.order, 'fro', data.N, new Float64Array( data.A ), data.LDA, work ), data.expectedFro, 'returns expected value' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlanhs, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 6', function test( t ) {
	t.strictEqual( dlanhs.length, 6, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var data;
	var work;
	var A;
	var i;

	data = ROW_MAJOR_DATA;

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	A = new Float64Array( data.A );
	work = new Float64Array( data.N );

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlanhs( value, 'max', data.N, A, data.LDA, work );
		};
	}
});

