	t.strictEqual( dlanhs( 'column-major', 'inf', 4, A, 4, work ), 15.0, 'returns expected value' );
	t.strictEqual( dlanhs( 'column-major', 'fro', 4, A, 4, work ), 14.203872711341791, 'returns expected value' );
	t.end();
